import { DEFAULT_LANGUAGE, LANGUAGES } from '@/utils/consts/locale';
import { REDIRECT_MAP } from '@/utils/consts/routes';
import createMiddleware from 'next-intl/middleware';
import { NextRequest, NextResponse } from "next/server";

const locales = LANGUAGES;
const defaultLocale = DEFAULT_LANGUAGE;

export const intlMiddleware = createMiddleware({
  locales: LANGUAGES,
  defaultLocale: DEFAULT_LANGUAGE,
  localePrefix: "as-needed"
});

export function handleLocaleDetection(request: NextRequest) {
  const { pathname } = request.nextUrl;

  if (REDIRECT_MAP[pathname]) {
    const redirectUrl = new URL(REDIRECT_MAP[pathname], request.url);
    return NextResponse.redirect(redirectUrl);
  }

  if (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api") ||
    pathname.startsWith("/static") ||
    pathname.includes(".")
  ) {
    return NextResponse.next();
  }

  return null;
}